INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (549, 1, 'PermitRootLogin 값의 뜻', 'SSH 서버 설정 파일 `/etc/ssh/sshd_config` 의 `PermitRootLogin` 은 **root 계정으로 직접 SSH 로그인**을 허용할지 정합니다. 값에 따라 비밀번호·키 중 무엇을 받을지가 달라집니다.

보안 담당이 "root 로는 **비밀번호든 키든 어떤 방식으로도** 직접 접속하지 못하게 하라"고 했습니다. 어떤 값을 써야 할까요?', '값마다 어떤 로그인 방식을 허용하는지 따져 보고, 허용 범위가 가장 좁은 값을 찾으세요.', NULL, NULL, '[]', 'choice', '["`PermitRootLogin prohibit-password`", "`PermitRootLogin no`", "`PermitRootLogin without-password`", "`PermitRootLogin yes`"]', 1, '`no` 는 root 직접 로그인을 모두 거부합니다. `prohibit-password`(옛 이름 `without-password`)는 **비밀번호만** 막고 **공개키 로그인은 허용**합니다(최신 OpenSSH 의 기본값). `yes` 는 둘 다 허용합니다. 관리 작업은 일반 계정으로 접속한 뒤 `sudo` 로 하는 것이 기록도 남기고 안전합니다. 단, 이 설정을 바꾼 뒤 일반 계정으로 로그인되는지 먼저 확인해 두어야 합니다.', NULL, NULL, NULL, NULL),
  (549, 2, '주석을 빼고 실제 적용되는 줄만 보기', '`/tmp/sshd_demo/sshd_config.sample` 은 Ubuntu 기본 `sshd_config` 와 비슷한 샘플입니다. 설명(`#` 로 시작)과 빈 줄이 많아 실제로 어떤 설정이 켜져 있는지 한눈에 안 보입니다.

**주석 줄과 빈 줄을 뺀 나머지**(실제 적용되는 줄)만 `/tmp/active.txt` 에 저장하세요. 원본 파일은 고치지 마세요.', '`#` 로 시작하는 줄과 빈 줄을 "제외"하는 옵션이 `grep` 에 있습니다. 두 조건을 한 번에 묶으려면 확장 정규식(`-E`)과 `|` 를 쓰세요.', 'cat /tmp/sshd_demo/sshd_config.sample
grep -vE ''^[[:space:]]*(#|$)'' /tmp/sshd_demo/sshd_config.sample > /tmp/active.txt
cat /tmp/active.txt   # Include, PermitRootLogin, KbdInteractiveAuthentication, UsePAM, X11Forwarding, PrintMotd
# ''#PasswordAuthentication yes'' 처럼 주석 처리된 줄은 적용되지 않는다 (기본값이 쓰인다)', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; cat > /tmp/sshd_demo/sshd_config.sample <<''EOF''\\n# This is the sshd server system-wide configuration file.\\n\\nInclude /etc/ssh/sshd_config.d/*.conf\\n\\n#Port 22\\nPermitRootLogin yes\\n#PubkeyAuthentication yes\\n\\n# To disable tunneled clear text passwords, change to no here!\\n#PasswordAuthentication yes\\n\\nKbdInteractiveAuthentication no\\nUsePAM yes\\nX11Forwarding yes\\nPrintMotd no\\nEOF\\n"]', '["sh", "-c", "( grep -vE ''^[[:space:]]*(#|$)'' /tmp/sshd_demo/sshd_config.sample | diff - /tmp/active.txt >/dev/null ) && ( grep -q ''^#PasswordAuthentication yes'' /tmp/sshd_demo/sshd_config.sample )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "주석·빈 줄을 뺀 내용과 정확히 같다", "cmd": ["sh", "-c", "grep -vE ''^[[:space:]]*(#|$)'' /tmp/sshd_demo/sshd_config.sample | diff - /tmp/active.txt >/dev/null"]}, {"label": "원본이 그대로다 (주석 줄이 남아 있다)", "cmd": ["sh", "-c", "grep -q ''^#PasswordAuthentication yes'' /tmp/sshd_demo/sshd_config.sample"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 3, 'root 로그인과 비밀번호 로그인 끄기', '`/tmp/sshd_demo/sshd_config` 는 연습용 SSH 서버 설정입니다. (실제 `/etc/ssh` 는 건드리지 않습니다.) 지금은 root 로그인이 허용돼 있고, `PasswordAuthentication` 은 주석 처리돼 있어 기본값(허용)이 적용됩니다.

이 파일을 고쳐서 **root 직접 로그인은 어떤 방식으로도 거부**하고 **비밀번호 로그인은 끄세요.** `Port 2222` 와 `PubkeyAuthentication yes` 는 그대로 두세요. `sshd -t -f 파일` 로 문법 검사가 통과해야 합니다.', '`#` 을 지우는 것만으로 값이 바뀌지는 않습니다. 줄 끝 값까지 확인하세요. 고친 뒤 `sshd -T -f 파일` 로 실제 적용값을 읽어 볼 수 있습니다.', 'cat /tmp/sshd_demo/sshd_config
sed -i ''s/^PermitRootLogin .*/PermitRootLogin no/; s/^#PasswordAuthentication .*/PasswordAuthentication no/'' /tmp/sshd_demo/sshd_config
sshd -t -f /tmp/sshd_demo/sshd_config && echo 문법 OK
sshd -T -f /tmp/sshd_demo/sshd_config | grep -E ''^(permitrootlogin|passwordauthentication|port)''
# 주석(#)을 풀고 값을 no 로 바꿔야 적용된다', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; cat > /tmp/sshd_demo/sshd_config <<''EOF''\\nPort 2222\\nPermitRootLogin yes\\n#PasswordAuthentication yes\\nPubkeyAuthentication yes\\nEOF\\n"]', '["sh", "-c", "( sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^permitrootlogin '' | grep -qx ''permitrootlogin no'' ) && ( sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no'' ) && ( sshd -t -f /tmp/sshd_demo/sshd_config && sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^port '' | grep -qx ''port 2222'' && sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^pubkeyauthentication '' | grep -qx ''pubkeyauthentication yes'' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "root 로그인이 no 로 적용된다", "cmd": ["sh", "-c", "sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^permitrootlogin '' | grep -qx ''permitrootlogin no''"]}, {"label": "비밀번호 로그인이 no 로 적용된다", "cmd": ["sh", "-c", "sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no''"]}, {"label": "포트·공개키 설정이 유지되고 문법이 맞다", "cmd": ["sh", "-c", "sshd -t -f /tmp/sshd_demo/sshd_config && sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^port '' | grep -qx ''port 2222'' && sshd -T -f /tmp/sshd_demo/sshd_config 2>/dev/null | grep -i ''^pubkeyauthentication '' | grep -qx ''pubkeyauthentication yes''"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 4, '재시작 전에 설정 문법만 검사하기', '`sshd_config` 를 고친 뒤 그냥 sshd 를 재시작했다가 **오타 하나로 서버가 아예 안 뜨면** 원격에서는 다시 접속할 방법이 없습니다. 그래서 재시작 전에 "서버를 띄우지 않고 **설정 파일의 문법·값만 검사**"합니다. 문법이 맞으면 아무것도 출력하지 않고 종료 코드 0 으로 끝나고, 틀리면 오류 줄 번호를 알려 줍니다. 빈칸에 알맞은 옵션을 넣으세요.', '"test"의 첫 글자입니다. 디버그나 포그라운드 실행 옵션은 서버를 실제로 띄웁니다.', NULL, NULL, '[]', 'fill', '["-t", "-D", "-d", "-e"]', NULL, '`sshd -t` 는 설정을 읽어 검사만 하고 끝납니다(성공하면 출력 없음, 종료 코드 0). `-D` 는 데몬화하지 않고 포그라운드로 **서버를 실행**, `-d` 는 디버그 모드로 서버를 실행(연결 한 번 뒤 종료), `-e` 는 로그를 표준 오류로 보내는 옵션이라 검사용이 아닙니다. `&&` 로 묶어 `sshd -t && systemctl reload sshd` 처럼 쓰면 검사가 실패할 때 적용을 막을 수 있습니다.', '[0]', 'sshd {0} -f /etc/ssh/sshd_config', NULL, NULL),
  (549, 5, 'sshd -t 로 오타 찾아 고치기', '`/tmp/sshd_demo/broken_config` 를 `sshd -t -f /tmp/sshd_demo/broken_config` 로 검사하면 오류가 납니다. 오류 메시지가 가리키는 **줄 번호와 옵션 이름**을 보고 고치세요. 고친 뒤 검사가 통과해야 하고, root 로그인은 `no`, 비밀번호 로그인은 `no`, 포트는 `2222` 로 적용돼야 합니다. (줄을 지우면 안 됩니다.)', '먼저 검사를 한 번 돌려 오류 메시지를 읽으세요. "Bad configuration option" 뒤에 문제의 옵션 이름이 나옵니다. 정확한 철자는 이 세트의 앞 문제에서 썼습니다.', 'sshd -t -f /tmp/sshd_demo/broken_config   # line 2: Bad configuration option: PermitRootLogn
sed -i ''s/PermitRootLogn /PermitRootLogin /'' /tmp/sshd_demo/broken_config
sshd -t -f /tmp/sshd_demo/broken_config && echo OK
# 오타가 난 채 서버를 재시작하면 sshd 가 못 떠서 원격 접속이 끊긴다. 항상 -t 로 먼저 확인', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; cat > /tmp/sshd_demo/broken_config <<''EOF''\\nPort 2222\\nPermitRootLogn no\\nPasswordAuthentication no\\nEOF\\n"]', '["sh", "-c", "( sshd -t -f /tmp/sshd_demo/broken_config ) && ( sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^permitrootlogin '' | grep -qx ''permitrootlogin no'' ) && ( sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no'' && sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^port '' | grep -qx ''port 2222'' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "문법 검사가 통과한다", "cmd": ["sh", "-c", "sshd -t -f /tmp/sshd_demo/broken_config"]}, {"label": "root 로그인이 no 로 적용된다", "cmd": ["sh", "-c", "sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^permitrootlogin '' | grep -qx ''permitrootlogin no''"]}, {"label": "비밀번호 로그인 no, 포트 2222 가 유지된다", "cmd": ["sh", "-c", "sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no'' && sshd -T -f /tmp/sshd_demo/broken_config 2>/dev/null | grep -i ''^port '' | grep -qx ''port 2222''"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 6, '같은 항목이 두 번 있으면 어느 줄이 이길까', '`/tmp/sshd_demo/first_config` 에는 `PermitRootLogin` 과 `PasswordAuthentication` 이 **위쪽과 아래쪽에 서로 다른 값으로 두 번씩** 적혀 있습니다. sshd 는 같은 항목이 여러 번 나오면 **가장 먼저 읽은 값**을 씁니다(나중 줄은 무시).

눈으로 추측하지 말고 `sshd -T -f 파일` 로 **실제 적용되는 값**을 뽑아, 두 항목의 줄(`permitrootlogin ...`, `passwordauthentication ...`)을 `/tmp/effective.txt` 에 저장하세요. (`sshd -T` 는 모든 항목을 소문자 키로 출력합니다.)', '`sshd -T` 출력에는 항목이 수십 개 나옵니다. 관심 있는 두 항목만 `grep -E` 로 걸러 파일로 보내세요.', 'sshd -T -f /tmp/sshd_demo/first_config | grep -E ''^(permitrootlogin|passwordauthentication) '' > /tmp/effective.txt
cat /tmp/effective.txt   # permitrootlogin no / passwordauthentication yes
# 위쪽 값이 이긴다: root 는 막혔지만, 비밀번호 로그인은 위쪽 yes 가 적용돼 열려 있다', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; cat > /tmp/sshd_demo/first_config <<''EOF''\\n# 보안 담당이 위쪽에 넣은 값과, 예전에 아래쪽에 남은 값이 섞여 있다\\nPermitRootLogin no\\nPasswordAuthentication yes\\nPort 22\\nPermitRootLogin yes\\nPasswordAuthentication no\\nEOF\\n"]', '["sh", "-c", "( grep -qx ''permitrootlogin no'' /tmp/effective.txt ) && ( grep -qx ''passwordauthentication yes'' /tmp/effective.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "root 로그인의 실효값 줄이 있다", "cmd": ["sh", "-c", "grep -qx ''permitrootlogin no'' /tmp/effective.txt"]}, {"label": "비밀번호 로그인의 실효값 줄이 있다", "cmd": ["sh", "-c", "grep -qx ''passwordauthentication yes'' /tmp/effective.txt"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 7, '설정 조각 파일이 내 설정을 덮는 문제', '`/tmp/sshd_demo/main_config` 에는 `PasswordAuthentication no` 라고 적혀 있는데, 맨 위 `Include` 가 `/tmp/sshd_demo/conf.d/*.conf` 조각 파일을 먼저 읽습니다. (Ubuntu 22.04 도 `sshd_config` 맨 위에서 `/etc/ssh/sshd_config.d/*.conf` 를 읽고, 클라우드 이미지가 거기에 `PasswordAuthentication yes` 를 넣어 두는 일이 흔합니다.)

`sshd -T -f /tmp/sshd_demo/main_config` 로 실제 적용값을 확인해 원인을 찾고, **비밀번호 로그인이 실제로 `no` 로 적용되도록** 고치세요. 검사(`sshd -t`)도 통과해야 합니다.', '`main_config` 의 값이 맞는데도 `yes` 로 나오는지 먼저 확인하세요. "먼저 읽은 값이 이긴다"는 규칙을 떠올리고, Include 된 파일 목록을 `ls` 로 보세요.', 'sshd -T -f /tmp/sshd_demo/main_config | grep passwordauthentication   # yes (조각 파일이 먼저 읽혀서 이긴다)
grep -rn PasswordAuthentication /tmp/sshd_demo
sed -i ''s/^PasswordAuthentication .*/PasswordAuthentication no/'' /tmp/sshd_demo/conf.d/50-cloud-init.conf
sshd -T -f /tmp/sshd_demo/main_config | grep passwordauthentication   # no
# 메인 파일만 고치지 말고, Include 되는 조각 파일까지 확인해야 한다', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; mkdir -p /tmp/sshd_demo/conf.d\\ncat > /tmp/sshd_demo/main_config <<''EOF''\\nInclude /tmp/sshd_demo/conf.d/*.conf\\nPort 22\\nPasswordAuthentication no\\nPubkeyAuthentication yes\\nEOF\\ncat > /tmp/sshd_demo/conf.d/50-cloud-init.conf <<''EOF''\\nPasswordAuthentication yes\\nEOF\\n"]', '["sh", "-c", "( sshd -T -f /tmp/sshd_demo/main_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no'' ) && ( sshd -t -f /tmp/sshd_demo/main_config )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "비밀번호 로그인이 no 로 적용된다", "cmd": ["sh", "-c", "sshd -T -f /tmp/sshd_demo/main_config 2>/dev/null | grep -i ''^passwordauthentication '' | grep -qx ''passwordauthentication no''"]}, {"label": "문법 검사가 통과한다", "cmd": ["sh", "-c", "sshd -t -f /tmp/sshd_demo/main_config"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 8, '비밀번호 로그인을 안전하게 끄는 순서', '원격 서버의 `PasswordAuthentication` 을 끄려고 합니다. 이미 접속해 있는 세션이 **하나뿐일 때** 설정을 잘못 건드리면 영영 못 들어갈 수 있으니, 아래 순서를 지킵니다. 먼저 **안전망 세션**(공개키로 로그인되는 별도 접속)을 열어 두고 닫지 않은 채, 설정을 고치고, 검사하고, 적용하고, 마지막에 새 접속으로 확인합니다. 카드를 알맞은 순서로 놓으세요.', '검사는 적용보다 앞이고, 되돌릴 길은 가장 먼저 확보합니다.', NULL, NULL, '[]', 'order', '["`sshd -t` 로 문법을 검사한다", "새 터미널에서 접속해 키로 로그인되는지 확인한다 (기존 세션은 그 뒤에 닫는다)", "공개키로 로그인되는 접속을 다른 터미널에 하나 더 열어 두고 닫지 않는다", "`systemctl reload sshd` 로 변경을 적용한다", "`sshd_config` 의 `PasswordAuthentication` 을 `no` 로 고친다"]', NULL, '안전망 세션 확보 → 설정 수정 → `sshd -t` 검사 → `reload` 적용 → 새 접속으로 확인 순서입니다. 이미 연결된 세션은 reload 해도 끊기지 않지만, 새 접속이 막히는 설정이라면 **기존 세션이 유일한 복구 수단**입니다. 키 로그인이 되는지 확인하기 전에 비밀번호 로그인부터 끄면 스스로를 잠그는 사고가 납니다(세트 124 의 마지막 주의와 같은 이야기입니다).', '[2, 4, 0, 3, 1]', NULL, NULL, NULL),
  (549, 9, 'ssh -L 포트 포워딩의 방향', '내 PC 에서는 사내 웹 서버 `web.example.com` 의 80 포트에 직접 갈 수 없지만, 중간 서버 `bastion.example.com` 에는 SSH 로 접속할 수 있고 bastion 은 `web.example.com` 에 닿습니다. 이때 다음 명령을 실행했습니다.

`ssh -L 8080:web.example.com:80 ops@bastion.example.com`

`-L 로컬포트:대상호스트:대상포트` 형태입니다. 이 명령의 효과로 가장 알맞은 것은 무엇일까요?', '`-L` 의 L 은 Local 입니다. 대상 호스트 이름은 어느 쪽에서 해석되는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["bastion 의 8080 포트가 열리고, 거기로 접속하면 내 PC 의 80 포트로 연결된다", "내 PC 의 8080 포트가 열리고, 거기로 접속하면 SSH 터널과 bastion 을 거쳐 `web.example.com:80` 에 연결된다", "`web.example.com` 의 8080 포트가 내 PC 에 복사돼 열린다", "bastion 의 80 포트가 영구적으로 닫힌다"]', 1, '`ssh -L` 은 **내 PC(명령을 실행한 쪽)에 대기 포트를 열고**, 그리로 들어온 연결을 SSH 터널로 서버에 보낸 뒤 **서버 쪽에서** 대상 `호스트:포트` 로 이어 줍니다. 그래서 브라우저에서 `http://localhost:8080` 을 열면 bastion 이 대신 접속한 `web.example.com:80` 이 보입니다. 반대 방향(서버 쪽에 포트를 열어 내 PC 로 끌어오기)은 `-R` 입니다. 포워딩은 SSH 로 암호화된 길이 생기는 것일 뿐 대상 서비스를 열거나 닫지는 않습니다.', NULL, NULL, NULL, NULL),
  (549, 10, 'ssh 설정 파일에 LocalForward 쓰기', '`-L` 옵션을 매번 치기 번거로우면 `ssh` 설정 파일에 적어 둡니다. `/tmp/sshd_demo/client_config` 에 별칭 `dbtunnel` 을 만드세요. 접속 주소 `bastion.example.com`, 사용자 `ops`, 그리고 **내 PC 의 13306 포트(바인드 주소 없이)로 들어오면 `db.example.com` 의 3306 포트로 전달**되는 포워딩입니다. (설정 파일 안에서 `-L` 에 해당하는 항목은 `LocalForward 로컬포트 대상호스트:대상포트` 입니다.) 접속하지 않고 `ssh -G -F /tmp/sshd_demo/client_config dbtunnel` 로 적용된 값을 확인할 수 있습니다.', '`Host` 줄 아래에 들여쓴 항목을 이어 씁니다. 접속 주소는 `HostName`, 사용자는 `User` 입니다. 마지막에 `ssh -G` 출력에서 `forward` 가 들어간 줄을 찾아 보세요.', 'printf ''%s\\n'' ''Host dbtunnel'' ''  HostName bastion.example.com'' ''  User ops'' ''  LocalForward 13306 db.example.com:3306'' > /tmp/sshd_demo/client_config
ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -iE ''^(hostname|user|localforward) ''
# 이제 ''ssh -N dbtunnel'' 만 실행해 두면 localhost:13306 으로 db 에 접속할 수 있다 (-N 은 명령 없이 터널만 유지)', '["sh", "-c", "rm -rf /tmp/sshd_demo /tmp/active.txt /tmp/effective.txt; mkdir -p /tmp/sshd_demo; cat > /tmp/sshd_demo/client_config <<''EOF''\\n# 아직 비어 있는 클라이언트 설정\\nEOF\\n"]', '["sh", "-c", "( ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -qx ''hostname bastion.example.com'' && ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -qx ''user ops'' ) && ( ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -Eqx ''localforward (\\\\[[0-9.]+\\\\]:)?13306 \\\\[db.example.com\\\\]:3306'' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "접속 주소와 사용자가 맞다", "cmd": ["sh", "-c", "ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -qx ''hostname bastion.example.com'' && ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -qx ''user ops''"]}, {"label": "13306 → db.example.com:3306 포워딩이 적용된다", "cmd": ["sh", "-c", "ssh -G -F /tmp/sshd_demo/client_config dbtunnel | grep -Eqx ''localforward (\\\\[[0-9.]+\\\\]:)?13306 \\\\[db.example.com\\\\]:3306''"]}]', '[{"title": "OpenSSH: sshd_config 매뉴얼", "url": "https://man.openbsd.org/sshd_config"}, {"title": "OpenSSH: ssh 매뉴얼 (-L 포트 포워딩)", "url": "https://man.openbsd.org/ssh"}, {"title": "tmux 위키: Getting Started", "url": "https://github.com/tmux/tmux/wiki/Getting-Started"}]'),
  (549, 11, '접속이 끊겨도 작업을 살리는 tmux', '서버에서 몇 시간 걸리는 백업을 돌리는 중에 노트북 Wi-Fi 가 끊기면, 일반 SSH 세션에서 실행한 작업은 **세션과 함께 종료**될 수 있습니다. `tmux` 는 서버 쪽에 "세션"을 만들어 두고, 접속이 끊겨도 그 안의 작업이 계속 돌게 해 주는 도구입니다. 가장 알맞은 사용 흐름은 무엇일까요?', '핵심은 "세션을 끝내지 않고 떼어 놓기(detach)"와 "나중에 다시 붙기(attach)"입니다. tmux 의 단축키는 먼저 `Ctrl-b` 를 누르고 손을 뗀 뒤 다음 키를 누릅니다.', NULL, NULL, '[]', 'choice', '["`tmux new -s backup` 안에서 작업을 돌리다가 `Ctrl-d` 를 눌러 나온다. 그러면 셸이 종료돼도 작업은 그대로 유지된다", "`tmux` 는 서버를 재부팅해도 세션과 작업을 자동으로 이어서 실행해 준다", "`Ctrl-c` 로 tmux 를 종료하면 안의 작업만 백그라운드로 남는다", "`tmux new -s backup` 으로 세션을 만들어 그 안에서 작업을 돌린다. 자리를 비울 때는 `Ctrl-b` 다음 `d` 로 떼어 놓고, 나중에 `tmux attach -t backup` 으로 다시 붙는다"]', 3, 'tmux 세션은 서버의 프로세스로 살아 있어서, SSH 가 끊겨도(또는 `Ctrl-b d` 로 detach 해도) 안의 작업은 계속 돕니다. 다시 접속해 `tmux ls` 로 세션 목록을 보고 `tmux attach -t 이름` 으로 붙으면 이어서 볼 수 있습니다. 세션 안의 셸에서 `Ctrl-d`(또는 `exit`)를 누르면 그 셸이 **종료**되고 마지막 창이면 세션도 사라집니다. `Ctrl-c` 는 실행 중인 명령을 중단합니다. 서버를 재부팅하면 tmux 세션도 사라집니다. 샌드박스에는 tmux 가 없어 개념만 다룹니다.', NULL, NULL, NULL, NULL),
  (549, 12, '떼어 둔 tmux 세션에 다시 붙기', '어제 `tmux new -s work` 로 만들어 두고 떼어 놓은(detach) 세션 `work` 가 있습니다. 오늘 서버에 SSH 로 다시 접속했습니다. 이미 있는 `work` 세션 **화면에 다시 붙는** 명령의 빈칸을 채우세요. (붙기 전에 `tmux ls` 로 어떤 세션이 있는지 목록을 볼 수 있습니다.)', '"붙이다"를 뜻하는 영어 단어입니다. 새로 만드는 것도, 끝내는 것도 아닙니다.', NULL, NULL, '[]', 'fill', '["attach", "kill-session", "new-window", "has-session"]', NULL, '`tmux attach -t 이름`(줄여서 `tmux a -t 이름`)이 떼어 둔 세션에 다시 붙습니다. `kill-session` 은 세션을 **끝내고**, `new-window` 는 그 세션에 창을 하나 더 만들 뿐 화면에는 붙지 않고, `has-session` 은 세션이 있는지만 종료 코드로 알려 줄 뿐 화면에 붙지 않습니다. 세션 이름을 붙여 두면(`-s 이름`) 여러 개가 있을 때 헷갈리지 않습니다.', '[0]', 'tmux {0} -t work', NULL, NULL);
